independent-practice.solution:
def is_palindrome(text):
    cleaned = ""
    for character in text:
        if character != " ":
            cleaned += character.lower()
    return cleaned == cleaned[::-1]

def tail(text, mark):
    at = text.rfind(mark)
    return text[at + 1:]

def shorten(text, limit):
    if len(text) <= limit:
        return text
    return text[:limit] + "..."
